package org.codex.nfsugpreview;
public final class SplitRowsTest {public static void main(String[] args){long checks=0;int[] heights={1,159,160,161,2160};for(int cut=1;cut<160;cut++)for(int height:heights)for(int owner=0;owner<2;owner++)for(int[] bounds:new int[][]{{0,160},{0,cut},{cut,160},{13,147},{79,81},{0,0},{160,160}}){NativeDrawBounds b=new NativeDrawBounds(11,229,bounds[0],bounds[1]);int[] clip=NativeSceneComposition.intersect(b,owner==0?0:cut,owner==0?cut:160).scissor(3240,height);for(int y=0;y<height;y++){long source=2L*height-2L*y-1;boolean expected=source*160>=2L*Math.max(bounds[0],owner==0?0:cut)*height&&source*160<2L*Math.min(bounds[1],owner==0?cut:160)*height;boolean actual=y>=clip[1]&&y<clip[1]+clip[3];if(expected!=actual)throw new AssertionError("Split row ownership cut="+cut+" height="+height+" y="+y);checks++;}}System.out.println("PASS_SPLIT_ROWS pixel_center_checks="+checks+" cuts=159 heights=5 owner_bounds_intersection=true");}}
